package com.travbook;
import com.travbook.journeys.application.port.in.*;
import com.travbook.journeys.application.port.out.*;
import com.travbook.journeys.domain.model.Journey.*;
import com.travbook.buses.application.port.in.DiscoverBuses;
import com.travbook.buses.domain.model.Bus;
import com.travbook.cabs.application.port.in.DiscoverCabs;
import com.travbook.cabs.domain.model.Cab;
import com.travbook.holidays.application.port.in.ExploreHolidays;
import com.travbook.holidays.domain.model.Holiday;
import com.travbook.customer.application.port.in.Customers;
import com.travbook.payments.application.port.in.*;
import com.travbook.shared.domain.*;
import com.travbook.support.TestIssuer;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.*;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.context.annotation.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.test.context.*;
import org.testcontainers.junit.jupiter.*;
import org.testcontainers.postgresql.PostgreSQLContainer;
import tools.jackson.databind.ObjectMapper;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.net.*;
import java.net.http.*;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"JOURNEY_WORKER_ENABLED=false","travbook.payments.refund-worker-enabled=false"})
@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
@Import(JourneyIntegrationTest.TimeConfig.class)
@Testcontainers class JourneyIntegrationTest {
 static TestIssuer issuer=new TestIssuer();@Container static PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:17.6-alpine");
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);r.add("travbook.oidc-issuer",issuer::url);r.add("travbook.local-identity",()->true);}
 @TestConfiguration static class TimeConfig{@Bean @Primary MutableClock testClock(){return new MutableClock();}}
 static class MutableClock extends Clock{Instant now=Instant.now();public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return Clock.fixed(now,z);}public Instant instant(){return now;}}
 @Autowired Journeys journeys;@Autowired ProcessJourneys worker;@Autowired JourneyStore store;@Autowired JourneyEffects effects;@Autowired DiscoverBuses buses;@Autowired DiscoverCabs cabs;@Autowired ExploreHolidays holidays;@Autowired PaymentRefunds refunds;@Autowired Customers customers;@Autowired MutableClock clock;@Autowired JdbcClient jdbc;@Autowired ObjectMapper json;@LocalServerPort int port;CustomerIdentity identity;String token;int day;
 @BeforeEach void init()throws Exception{clock.now=Instant.now();identity=new CustomerIdentity(issuer.url(),"journey-"+UUID.randomUUID());customers.resolve(identity);token=issuer.token(identity.subject(),"bookings:read bookings:write");day=10+Math.floorMod(identity.subject().hashCode(),50);}
 static { Runtime.getRuntime().addShutdownHook(new Thread(issuer::close,"journey-test-issuer-cleanup")); }
 String key(){return UUID.randomUUID().toString();}UUID correlation(){return UUID.randomUUID();}
 Request bus(){var p=buses.search(new Bus.Criteria(Bus.City.DELHI,Bus.City.JAIPUR,LocalDate.now(clock).plusDays(day),List.of(30)));var t=p.items().getFirst();return new Request(Kind.BUS,p.id(),t.id(),List.of("L1"),t.boarding().getFirst().id(),t.dropping().getFirst().id());}
 Request cab(){var p=cabs.search(new Cab.Criteria(Cab.Type.AIRPORT,Cab.Place.DELHI_AIRPORT,Cab.Place.DELHI_CENTRE,LocalDate.now(clock).plusDays(day),"10:00",null,null,1,1,0));return new Request(Kind.CAB,p.id(),p.items().getFirst().id(),List.of(),null,null);}
 Request holiday(boolean enquiry){var p=holidays.detail(enquiry?"sample-goa-coast":"sample-jaipur-culture");var q=holidays.quote(identity,new Holiday.Selection(p.id(),p.departures().getFirst(),1,List.of(),Holiday.Upgrade.STANDARD,false),key(),correlation());if(enquiry)holidays.enquire(identity,q.id(),new Holiday.Contact("Sample Person","sample@example.test",""),true,key(),correlation());return new Request(Kind.HOLIDAY,q.id(),null,List.of(),null,null);}
 Booking book(Request r,Scenario scenario){var q=journeys.quote(identity,r,key(),correlation());journeys.accept(identity,q.quote().id(),1,true,key(),correlation());return journeys.book(identity,q.quote().id(),List.of(new Passenger("Sample Person",30)),"sample@example.test",scenario,key(),correlation());}
 Booking advance(Booking b,Status until){for(int i=0;i<100;i++){b=journeys.booking(identity,b.id());if(b.status()==until&&(until!=Status.FAILED||b.step()==Step.DONE))return b;worker.tick();clock.now=clock.now.plusMillis(100);}throw new AssertionError("Did not reach "+until+": "+b.status()+" / "+b.step());}
 Booking finish(Booking b){if(b.status()==Status.HOLD_PENDING)b=advance(b,Status.AWAITING_PAYMENT);journeys.pay(identity,b.id(),"pay-"+b.id(),correlation());return advance(b,Status.CONFIRMED);}
 HttpResponse<String> call(String path,String auth)throws Exception{return HttpClient.newHttpClient().send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).header("Authorization","Bearer "+auth).GET().build(),HttpResponse.BodyHandlers.ofString());}
 @Test void allThreeServicesConfirmProduceProtectedDocumentsAndRefund(){for(Request r:List.of(bus(),cab(),holiday(false))){var b=finish(book(r,Scenario.NORMAL));assertThat(b.payment()).isEqualTo(Payment.CAPTURED);assertThat(b.reservation()).isEqualTo(Reservation.CONFIRMED);var doc=journeys.document(identity,b.id());assertThat(doc.content()).contains("NOT VALID FOR TRAVEL",b.supplierReference());assertThat(doc).isEqualTo(journeys.document(identity,b.id()));assertThat(jdbc.sql("select count(*) from journey_supplier_component where booking_id=:id and status='CONFIRMED'").param("id",b.id()).query(Integer.class).single()).isEqualTo(b.quote().selection().components().size());var q=journeys.cancellationQuote(identity,b.id(),key(),correlation());var cancel=journeys.cancel(identity,b.id(),q.id(),true,false,key(),correlation());for(int i=0;i<40;i++){worker.tick();refunds.settleNext();clock.now=clock.now.plusSeconds(1);cancel=journeys.booking(identity,b.id());if(cancel.step()==Step.DONE)break;}assertThat(cancel.status()).isEqualTo(Status.CANCELLED);assertThat(cancel.refund()).isEqualTo(Refund.SUCCEEDED);UUID id=b.id();assertThatThrownBy(()->journeys.document(identity,id)).isInstanceOf(DomainFailure.class);assertThat(jdbc.sql("select count(*) from journey_supplier_component where booking_id=:id and status='CONFIRMED'").param("id",id).query(Integer.class).single()).isZero();}}
 @Test void busSeatsAreExclusiveAcrossSearchesAndHoldsExpire()throws Exception{day=65;var first=book(bus(),Scenario.NORMAL);var second=book(bus(),Scenario.NORMAL);try(var pool=Executors.newFixedThreadPool(2)){for(var task:pool.invokeAll(List.<Callable<Boolean>>of(()->worker.tick(),()->worker.tick())))assertThat(task.get()).isTrue();}for(int n=0;n<20;n++){worker.tick();first=journeys.booking(identity,first.id());second=journeys.booking(identity,second.id());if(first.status()!=Status.HOLD_PENDING&&second.status()!=Status.HOLD_PENDING)break;}assertThat(List.of(first.status(),second.status())).containsExactlyInAnyOrder(Status.AWAITING_PAYMENT,Status.FAILED);if(first.status()==Status.FAILED){var swap=first;first=second;second=swap;}assertThat(buses.trip(second.quote().selection().request().sourceId(),second.quote().selection().request().offerId(),true).trip().seats()).anyMatch(seat->seat.id().equals("L1")&&seat.status()==Bus.SeatStatus.OCCUPIED);assertThat(second.failure()).isEqualTo("SEAT_UNAVAILABLE");clock.now=first.quote().expiresAt().plusSeconds(1);first=advance(first,Status.FAILED);assertThat(first.reservation()).isEqualTo(Reservation.RELEASED);assertThat(jdbc.sql("select count(*) from payment_account where id=:id").param("id",first.id()).query(Integer.class).single()).isZero();var third=book(bus(),Scenario.NORMAL);assertThat(advance(third,Status.AWAITING_PAYMENT).reservation()).isEqualTo(Reservation.HELD);}
 @Test void ownedQuoteAcceptanceAgeExpiryAndDuplicateBookingAreEnforced()throws Exception{var q=journeys.quote(identity,cab(),key(),correlation());assertThatThrownBy(()->journeys.book(identity,q.quote().id(),List.of(new Passenger("Sample",30)),"a@example.test",Scenario.NORMAL,key(),correlation())).isInstanceOf(DomainFailure.class).hasMessageContaining("Accept");journeys.accept(identity,q.quote().id(),1,true,key(),correlation());String k=key();var a=journeys.book(identity,q.quote().id(),List.of(new Passenger("Sample",30)),"a@example.test",Scenario.NORMAL,k,correlation());assertThat(journeys.book(identity,q.quote().id(),List.of(new Passenger("Sample",30)),"a@example.test",Scenario.NORMAL,k,correlation()).id()).isEqualTo(a.id());assertThatThrownBy(()->journeys.book(identity,q.quote().id(),List.of(new Passenger("Changed",30)),"a@example.test",Scenario.NORMAL,k,correlation())).isInstanceOf(DomainFailure.class);assertThat(call("/api/v1/journey-bookings/"+a.id(),issuer.token("other-journey","bookings:read")).statusCode()).isEqualTo(404);assertThat(call("/api/v1/journey-bookings/"+a.id(),token).statusCode()).isEqualTo(200);clock.now=q.quote().expiresAt();assertThatThrownBy(()->journeys.pay(identity,a.id(),key(),correlation())).isInstanceOf(DomainFailure.class).hasMessageContaining("expired");}
 @Test void rejectedReservationAfterCaptureIsRefundedNotConfirmed(){var b=book(cab(),Scenario.RESERVATION_REJECTED);journeys.pay(identity,b.id(),key(),correlation());for(int i=0;i<60;i++){worker.tick();refunds.settleNext();clock.now=clock.now.plusSeconds(1);b=journeys.booking(identity,b.id());if(b.step()==Step.DONE)break;}assertThat(b.status()).isEqualTo(Status.FAILED);assertThat(b.payment()).isEqualTo(Payment.CAPTURED);assertThat(b.refund()).isEqualTo(Refund.SUCCEEDED);assertThat(b.reservation()).isEqualTo(Reservation.RELEASED);UUID id=b.id();assertThatThrownBy(()->journeys.document(identity,id)).isInstanceOf(DomainFailure.class);}
 @Test void declinedPaymentsNeverConfirmOrLeaveSeatAllocation(){for(var scenario:List.of(Scenario.AUTH_DECLINED,Scenario.CAPTURE_DECLINED)){var b=book(cab(),scenario);journeys.pay(identity,b.id(),key(),correlation());b=advance(b,Status.FAILED);assertThat(b.payment()).isIn(Payment.DECLINED,Payment.VOIDED);assertThat(b.refund()).isEqualTo(Refund.NONE);}}
 @Test void lostEffectAcknowledgementsRecoverWithoutDuplicateCharges(){var b=finish(book(cab(),Scenario.RESPONSE_LOST));assertThat(b.status()).isEqualTo(Status.CONFIRMED);assertThat(jdbc.sql("select count(*) from journey_supplier_receipt where booking_id=:id and step='RESERVE'").param("id",b.id()).query(Integer.class).single()).isEqualTo(1);assertThat(journeys.list(identity,null).items()).extracting(Booking::id).contains(b.id());}
 @Test void expiredLeaseRejectsStaleWorkerAndRecoversKnownEffect(){var b=book(cab(),Scenario.NORMAL);journeys.pay(identity,b.id(),key(),correlation());worker.tick();var claim=store.claim().orElseThrow();assertThat(claim.booking().step()).isEqualTo(Step.AUTHORIZE);var result=effects.execute(claim.booking(),Step.AUTHORIZE);jdbc.sql("update journey_work set lease_until=clock_timestamp()-interval '1 second' where booking_id=:id").param("id",b.id()).update();assertThat(store.complete(claim,claim.booking().result(result.accepted(),true,result.reference(),clock.instant()))).isFalse();assertThat(advance(b,Status.CONFIRMED).payment()).isEqualTo(Payment.CAPTURED);}
 @Test void holidayEnquiryRequiresNewOwnedTermsAndAllComponents(){var r=holiday(true);var b=finish(book(r,Scenario.NORMAL));assertThat(b.quote().selection().components()).hasSize(3);assertThat(b.quote().selection().details().getFirst()).contains("MOCK supplier quotation");assertThat(holidays.enquiryForQuote(identity,r.sourceId())).isNotNull();}
 @Test void transactionFailureRollsBackBookingCommandAndOutbox(){var q=journeys.quote(identity,cab(),key(),correlation());journeys.accept(identity,q.quote().id(),1,true,key(),correlation());jdbc.sql("create function journey_event_failure() returns trigger language plpgsql as $$ begin raise exception 'Injected event failure'; end $$").update();jdbc.sql("create trigger journey_event_failure before insert on journey_outbox for each row execute function journey_event_failure()").update();String k=key();try{assertThatThrownBy(()->journeys.book(identity,q.quote().id(),List.of(new Passenger("Sample",30)),"a@example.test",Scenario.NORMAL,k,correlation())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(journeys.quote(identity,q.quote().id()).bookingId()).isNull();}finally{jdbc.sql("drop trigger journey_event_failure on journey_outbox").update();jdbc.sql("drop function journey_event_failure()").update();}assertThat(journeys.book(identity,q.quote().id(),List.of(new Passenger("Sample",30)),"a@example.test",Scenario.NORMAL,k,correlation()).id()).isNotNull();}
 @Test void realProcessCrashAfterCaptureRecoversOneLedgerEffect()throws Exception{var b=book(cab(),Scenario.NORMAL);journeys.pay(identity,b.id(),key(),correlation());while(journeys.booking(identity,b.id()).step()!=Step.CAPTURE)worker.tick();var claim=store.claim().orElseThrow();assertThat(claim.booking().id()).isEqualTo(b.id());var log=java.nio.file.Files.createTempFile("journey-crash-",".log");try{var cp=System.getProperty("surefire.test.class.path",System.getProperty("java.class.path"));var pb=new ProcessBuilder(java.nio.file.Path.of(System.getProperty("java.home"),"bin","java").toString(),"-cp",cp,"com.travbook.support.JourneyProcess",b.quote().owner().toString(),b.id().toString(),"CAPTURE").redirectErrorStream(true).redirectOutput(log.toFile());pb.environment().put("DATABASE_URL",postgres.getJdbcUrl());pb.environment().put("DATABASE_USERNAME",postgres.getUsername());pb.environment().put("DATABASE_PASSWORD",postgres.getPassword());var process=pb.start();boolean done=process.waitFor(30,TimeUnit.SECONDS);if(!done)process.destroyForcibly();assertThat(done).isTrue();assertThat(process.exitValue()).withFailMessage(java.nio.file.Files.readString(log)).isEqualTo(29);}finally{java.nio.file.Files.deleteIfExists(log);}jdbc.sql("update journey_work set lease_until=clock_timestamp()-interval '1 second' where booking_id=:id").param("id",b.id()).update();assertThat(advance(b,Status.CONFIRMED).payment()).isEqualTo(Payment.CAPTURED);assertThat(jdbc.sql("select count(*) from payment_journal where payment_id=:id").param("id",b.id()).query(Integer.class).single()).isEqualTo(2);}
 @Test void delayedRefundDuplicateCancellationAndImmutableRecords(){var b=finish(book(cab(),Scenario.NORMAL));var q=journeys.cancellationQuote(identity,b.id(),key(),correlation());String k=key();journeys.cancel(identity,b.id(),q.id(),true,true,k,correlation());assertThat(journeys.cancel(identity,b.id(),q.id(),true,true,k,correlation()).id()).isEqualTo(b.id());for(int i=0;i<10&&journeys.booking(identity,b.id()).step()!=Step.REFUND_STATUS;i++)worker.tick();var pending=journeys.booking(identity,b.id());assertThat(pending.status()).isEqualTo(Status.CANCELLED);assertThat(pending.refund()).isEqualTo(Refund.PENDING);assertThatThrownBy(()->journeys.cancel(identity,b.id(),q.id(),true,false,k,correlation())).isInstanceOf(DomainFailure.class);for(int i=0;i<50;i++){clock.now=clock.now.plusSeconds(5);refunds.settleNext();worker.tick();if(journeys.booking(identity,b.id()).step()==Step.DONE)break;}assertThat(journeys.booking(identity,b.id()).refund()).isEqualTo(Refund.SUCCEEDED);assertThat(jdbc.sql("select count(*) from payment_refund_journal j join payment_refund r on r.operation_id=j.operation_id where r.payment_id=:id").param("id",b.id()).query(Integer.class).single()).isEqualTo(2);for(String table:List.of("journey_quote","journey_document","journey_outbox","journey_supplier_receipt"))assertThatThrownBy(()->jdbc.sql("delete from "+table).update()).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void mismatchedSupplierReceiptRemainsUncertainWithoutFalseTicket(){var b=book(cab(),Scenario.NORMAL);journeys.pay(identity,b.id(),key(),correlation());for(int n=0;n<30&&journeys.booking(identity,b.id()).step()!=Step.RESERVE;n++)worker.tick();var current=journeys.booking(identity,b.id());assertThat(current.payment()).isEqualTo(Payment.CAPTURED);var fake=new JourneySupplier.Receipt(current.operation(Step.RESERVE),current.id(),Step.RESERVE,"wrong-binding",true,"MOCK-JOURNEY-"+current.id(),"MOCK");jdbc.sql("insert into journey_supplier_receipt(operation_id,booking_id,step,payload) values(:op,:id,'RESERVE',cast(:p as jsonb))").param("op",fake.operationId()).param("id",fake.bookingId()).param("p",json.writeValueAsString(fake)).update();for(int n=0;n<30;n++){worker.tick();clock.now=clock.now.plusSeconds(10);if(journeys.booking(identity,b.id()).status()==Status.REVIEW)break;}var review=journeys.booking(identity,b.id());assertThat(review.status()).isEqualTo(Status.REVIEW);assertThat(review.step()).isEqualTo(Step.RESERVE);assertThat(review.payment()).isEqualTo(Payment.CAPTURED);assertThatThrownBy(()->journeys.document(identity,b.id())).isInstanceOf(DomainFailure.class);}
 @Test void concurrentDuplicateBookingUsesOneAggregate()throws Exception{var q=journeys.quote(identity,cab(),key(),correlation());journeys.accept(identity,q.quote().id(),1,true,key(),correlation());String k=key();try(var pool=Executors.newFixedThreadPool(2)){var calls=pool.invokeAll(List.<Callable<Booking>>of(()->journeys.book(identity,q.quote().id(),List.of(new Passenger("Sample",30)),"a@example.test",Scenario.NORMAL,k,correlation()),()->journeys.book(identity,q.quote().id(),List.of(new Passenger("Sample",30)),"a@example.test",Scenario.NORMAL,k,correlation())));assertThat(calls.get(0).get().id()).isEqualTo(calls.get(1).get().id());}}
}
